        if row[c]==7: row[c]=1
    print(' '.join(map(str,row)))

# best alignment of 4x blocks across row order/reflection and column reversal
for revrows in [False,True]:
 for revcols in [False,True]:
  A=U[::-1] if revrows else U
  B=L[:,::-1] if revcols else L
  best=[]
  for dx in range(-13,14):
   m=t=0
   for x in range(28):
    y=x-dx
